import{_ as a}from"./chunks/homes-app-landing-page.DNARoO1d.js";import{_ as t,o as r,c as n,aj as o,j as i}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"Build your first Angular app","description":"","frontmatter":{},"headers":[],"relativePath":"en/tutorials/first-app.md","filePath":"en/tutorials/first-app.md"}'),l={name:"en/tutorials/first-app.md"};function s(u,e,p,d,c,h){return r(),n("div",null,e[0]||(e[0]=[o('<h1 id="build-your-first-angular-app" tabindex="-1">Build your first Angular app <a class="header-anchor" href="#build-your-first-angular-app" aria-label="Permalink to &quot;Build your first Angular app&quot;">​</a></h1><p>This tutorial consists of lessons that introduce the Angular concepts you need to know to start coding in Angular.</p><p>You can do as many or as few as you would like and you can do them in any order.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>Prefer video? We also have a full <a href="https://youtube.com/playlist?list=PL1w1q3fL4pmj9k1FrJ3Pe91EPub2_h4jF&amp;si=1q9889ulHp8VZ0e7" target="_blank" rel="noreferrer">YouTube course</a> for this tutorial!</p></div>',4),i("iframe",{src:"https://www.youtube.com/embed/xAT0lHYhHMY?si=cKUW_MGn3MesFT7o",title:"Video",style:{width:"100%","aspect-ratio":"16/9",border:"0"},allowfullscreen:""},null,-1),o('<h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>For the best experience with this tutorial, review these requirements to make sure you have what you need to be successful.</p><h3 id="your-experience" tabindex="-1">Your experience <a class="header-anchor" href="#your-experience" aria-label="Permalink to &quot;Your experience&quot;">​</a></h3><p>The lessons in this tutorial assume that you have experience with the following:</p><ol><li>Creating HTML web pages by editing the HTML directly.</li><li>Programming web site content in JavaScript.</li><li>Reading Cascading Style Sheet (CSS) content and understanding how selectors are used.</li><li>Using command-line instructions to perform tasks on your computer.</li></ol><h3 id="your-equipment" tabindex="-1">Your equipment <a class="header-anchor" href="#your-equipment" aria-label="Permalink to &quot;Your equipment&quot;">​</a></h3><p>These lessons can be completed using a local installation of the Angular tools or in our embedded editor. Local Angular development can be completed on Windows, macOS or Linux based systems.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Look for alerts like this one, which call out steps that may only be for your local editor.</p></div><h2 id="conceptual-preview-of-your-first-angular-app" tabindex="-1">Conceptual preview of your first Angular app <a class="header-anchor" href="#conceptual-preview-of-your-first-angular-app" aria-label="Permalink to &quot;Conceptual preview of your first Angular app&quot;">​</a></h2><p>The lessons in this tutorial create an Angular app that lists houses for rent and shows the details of individual houses. This app uses features that are common to many Angular apps.</p><img alt="Output of homes landing page" src="'+a+'"><h2 id="local-development-environment" tabindex="-1">Local development environment <a class="header-anchor" href="#local-development-environment" aria-label="Permalink to &quot;Local development environment&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>This step is only for your local environment!</p></div><p>Perform these steps in a command-line tool on the computer you want to use for this tutorial.</p><h3 id="_1-identify-the-version-of-node-js-that-angular-requires" tabindex="-1">1. Identify the version of <code>node.js</code> that Angular requires <a class="header-anchor" href="#_1-identify-the-version-of-node-js-that-angular-requires" aria-label="Permalink to &quot;1. Identify the version of `node.js` that Angular requires&quot;">​</a></h3><p>Angular requires an active LTS or maintenance LTS version of Node. Let&#39;s confirm your version of <code>node.js</code>. For information about specific version requirements, see the engines property in the <a href="https://unpkg.com/browse/@angular/core@15.1.5/package.json" target="_blank" rel="noreferrer">package.json file</a>.</p><p>From a <strong>Terminal</strong> window:</p><ol><li>Run the following command: <code>node --version</code></li><li>Confirm that the version number displayed meets the requirements.</li></ol><h3 id="_2-install-the-correct-version-of-node-js-for-angular" tabindex="-1">2. Install the correct version of <code>node.js</code> for Angular <a class="header-anchor" href="#_2-install-the-correct-version-of-node-js-for-angular" aria-label="Permalink to &quot;2. Install the correct version of `node.js` for Angular&quot;">​</a></h3><p>If you do not have a version of <code>node.js</code> installed, please follow the <a href="https://nodejs.org/en/download/" target="_blank" rel="noreferrer">directions for installation on nodejs.org</a></p><h3 id="_3-install-the-latest-version-of-angular" tabindex="-1">3. Install the latest version of Angular <a class="header-anchor" href="#_3-install-the-latest-version-of-angular" aria-label="Permalink to &quot;3. Install the latest version of Angular&quot;">​</a></h3><p>With <code>node.js</code> and <code>npm</code> installed, the next step is to install the <a href="/en/tools/cli">Angular CLI</a> which provides tooling for effective Angular development.</p><p>From a <strong>Terminal</strong> window run the following command: <code>npm install -g @angular/cli</code>.</p><h3 id="_4-install-integrated-development-environment-ide" tabindex="-1">4. Install integrated development environment (IDE) <a class="header-anchor" href="#_4-install-integrated-development-environment-ide" aria-label="Permalink to &quot;4. Install integrated development environment (IDE)&quot;">​</a></h3><p>You are free to use any tool you prefer to build apps with Angular. We recommend the following:</p><ol><li><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a><ul><li>As an optional but recommended step, you can further improve your developer experience by installing the <a href="https://marketplace.visualstudio.com/items?itemName=Angular.ng-template" target="_blank" rel="noreferrer">Angular Language Service</a></li></ul></li><li><a href="https://www.jetbrains.com/webstorm/" target="_blank" rel="noreferrer">WebStorm</a></li></ol><h3 id="_5-optional-set-up-your-ai-powered-ide" tabindex="-1">5. Optional: set-up your AI powered IDE <a class="header-anchor" href="#_5-optional-set-up-your-ai-powered-ide" aria-label="Permalink to &quot;5. Optional: set-up your AI powered IDE&quot;">​</a></h3><p>In case you&#39;re following this tutorial in your preferred AI powered IDE, <a href="/en/ai/develop-with-ai">check out Angular prompt rules and best practices</a>.</p><p>For more information about the topics covered in this lesson, visit:</p><ul><li><a href="/en/overview">What is Angular</a></li><li><a href="/en/tools/cli/setup-local">Setting up the local environment and workspace</a></li><li><a href="/en/cli">Angular CLI Reference</a></li></ul>',30)]))}const v=t(l,[["render",s]]);export{g as __pageData,v as default};
